      SUBROUTINE FNDNAM(KNAME,LNAME,INAME)CC     FIND AND DECODE MATRIX ELEMENT NAME OR CONSTRAINABLE PARAMETER     CC----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ICODE.CIN'C ---------------------------------------------------------------------      CHARACTER*15    KNAME, KNAMM      CHARACTER*1     KLETS(8)      EQUIVALENCE     (KNAMM,KLETS(1))C      KNAMM = KNAME      ICODE = 0      JCODE = 0      INUM = 2      INAME = 0CC     FIRST-ORDER MATRIX CONSTRAINTC      IF (KLETS(1) .EQ. 'R' .AND. KLETS(2) .NE. 'O') THEN        IF (KLETS(2) .EQ. 'A') INUM = 3        IF (LNAME .NE. INUM + 1) GO TO 300        IND1 = INDEX('123456',KLETS(INUM))        IND2 = INDEX('123456',KLETS(INUM+1))        IF (IND1 .EQ. 0 .OR. IND2 .EQ. 0) GO TO 300        IF (INUM .EQ. 4) ICODE = - 20        ICODE = ICODE - IND1        JCODE = IND2        GO TO 200CC     SECOND ORDER MATRIX CONSTRAINTC      ELSE IF (KLETS(1) .EQ. 'T') THEN        IF (KLETS(2) .EQ. 'A') INUM = 3        IF (LNAME .NE. INUM + 2) GO TO 300        IND1 = INDEX('123456',KLETS(INUM))        IND2 = INDEX('123456',KLETS(INUM+1))        IND3 = INDEX('123456',KLETS(INUM+2))        IF (IND1 .EQ. 0 .OR. IND2 .EQ. 0 .OR. IND3 .EQ. 0) GO TO 300        IF (INUM .EQ. 5) ICODE = - 20        ICODE = ICODE - IND1        JCODE = 10*IND2 + IND3        GO TO 200CC     THIRD-ORDER MATRIX CONSTRAINTC      ELSE IF (KLETS(1) .EQ. 'U') THEN        IF (KLETS(2) .EQ. 'A') INUM = 3        IF (LNAME .NE. INUM + 3) GO TO 300        IND1 = INDEX('123456',KLETS(INUM))        IND2 = INDEX('123456',KLETS(INUM+1))        IND3 = INDEX('123456',KLETS(INUM+2))        IND4 = INDEX('123456',KLETS(INUM+3))        IF (IND1 .EQ. 0 .OR. IND2 .EQ. 0 .OR. IND3 .EQ. 0 .OR.     1      IND4 .EQ. 0) GO TO 300        IF (INUM .EQ. 6) ICODE = - 20        ICODE = ICODE - IND1        JCODE = 100*IND2 + 10*IND3 + IND4        GO TO 200CC     BEAM MATRIX CONSTRAINTC      ELSE IF (KLETS(1) .EQ. 'S' .AND. KLETS(2) .NE. 'E'     1   .AND. KLETS(2) .NE. 'Q') THEN        IF (LNAME .NE. 3) GO TO 300        IND1 = INDEX('123456',KLETS(INUM))        IND2 = INDEX('123456',KLETS(INUM+1))        IF (IND1 .EQ. 0 .OR. IND2 .EQ. 0) GO TO 300        ICODE = IND1        JCODE = IND2        GO TO 200CC     BEAM CORRELATION CONSTRAINTC      ELSE IF (KLETS(1) .EQ. 'C') THEN        IF (LNAME .NE. 3) GO TO 300        IND1 = INDEX('123456',KLETS(INUM))        IND2 = INDEX('123456',KLETS(INUM+1))        IF (IND1 .EQ. 0 .OR. IND2 .EQ. 0) GO TO 300        ICODE = 10 + IND1        JCODE = IND2        GO TO 200CC     BEAM SIZE CONSTRAINTC      ELSE IF (KNAMM .EQ. 'XBEAM' .OR. KNAMM .EQ. 'XPBEAM'     1        .OR. KNAMM .EQ. 'YBEAM' .OR. KNAMM .EQ. 'YPBEAM'     2        .OR. KNAMM .EQ. 'DLBEAM' .OR. KNAMM .EQ. 'DELBEAM')     3        THEN        IF (KNAMM .EQ. 'XBEAM') ICODE = 1        IF (KNAMM .EQ. 'XPBEAM') ICODE = 2        IF (KNAMM .EQ. 'YBEAM') ICODE = 3        IF (KNAMM .EQ. 'YPBEAM') ICODE = 4        IF (KNAMM .EQ. 'DLBEAM') ICODE = 5        IF (KNAMM .EQ. 'DELBEAM') ICODE = 6        JCODE = ICODE        GO TO 200CC     BEAM FIRST MOMENT CONSTRAINTC      ELSE IF (KNAMM .EQ. 'XC' .OR. KNAMM .EQ. 'XPC'     1        .OR. KNAMM .EQ. 'YC' .OR. KNAMM .EQ. 'YPC'     2        .OR. KNAMM .EQ. 'DLC' .OR. KNAMM .EQ. 'DELC') THEN        ICODE = 7        IF (KNAMM .EQ. 'XC') JCODE = 1        IF (KNAMM .EQ. 'XPC') JCODE = 2        IF (KNAMM .EQ. 'YC') JCODE = 3        IF (KNAMM .EQ. 'YPC') JCODE = 4        IF (KNAMM .EQ. 'DLC') JCODE = 5        IF (KNAMM .EQ. 'DELC') JCODE = 6        GO TO 200CC     BEAM LENGTH CONSTRAINTC      ELSE IF (KNAMM .EQ. 'L') THEN        ICODE = 0        JCODE  = 0        GO TO 200CC     AGS MACHINE CONSTRAINTC      ELSE IF (KNAMM .EQ. 'MUX'.OR. KNAMM .EQ. 'MUY') THEN        IF (KNAMM .EQ. 'MUX') THEN          IND1 = 1          IND2 = 2        ELSE IF (KNAMM .EQ. 'MUY') THEN          IND1 = 3          IND2 = 4        ENDIF        ICODE = - 10 - IND1        JCODE = IND2        GO TO 200CC     BEAM FIRST MOMENT CONSTRAINTC      ELSE IF (KNAMM .EQ. 'X' .OR. KNAMM .EQ. 'XP'     1 .OR. KNAMM .EQ. 'Y' .OR. KNAMM .EQ. 'YP'     2 .OR. KNAMM .EQ. 'DL' .OR. KNAMM .EQ. 'DEL') THEN        ICODE = 0        IF (KNAMM .EQ. 'X')   JCODE = 1        IF (KNAMM .EQ. 'XP')  JCODE = 2        IF (KNAMM .EQ. 'Y')   JCODE = 3        IF (KNAMM .EQ. 'YP')  JCODE = 4        IF (KNAMM .EQ. 'DL')  JCODE = 5        IF (KNAMM .EQ. 'DEL') JCODE = 6        GO TO 200CC     FLOOR COORDINATE CONSTRAINTC      ELSE        IF (KNAMM .EQ. 'XFLOOR') JCODE = 1        IF (KNAMM .EQ. 'YFLOOR') JCODE = 2        IF (KNAMM .EQ. 'ZFLOOR') JCODE = 3        IF (KNAMM .EQ. 'YAW')    JCODE = 4        IF (KNAMM .EQ. 'PITCH')  JCODE = 5        IF (KNAMM .EQ. 'ROLL')   JCODE = 6        IF (KNAMM(1:4) .EQ. 'ELEV') JCODE = 7        IF (JCODE .NE. 0) THEN          ICODE = 8          GO TO 200        ENDIFCC     ACCELERATOR FUNCTION CONSTRAINTC        IF (KNAMM .EQ. 'BETAX') JCODE = 1        IF (KNAMM .EQ. 'ALPHAX') JCODE = 2        IF (KNAMM .EQ. 'BETAY') JCODE = 3        IF (KNAMM .EQ. 'ALPHAY') JCODE = 4        IF (KNAMM .EQ. 'SQBX') JCODE = 7        IF (KNAMM .EQ. 'SQBY') JCODE = 8        IF (JCODE .NE. 0) THEN          ICODE = JCODE + 20          GO TO 200        ENDIFCC     ACCELERATOR FUNCTION ETA CONSTRAINTC        IF (KNAMM .EQ. 'ETAX')  JCODE = 1        IF (KNAMM .EQ. 'DETAX') JCODE = 2        IF (KNAMM .EQ. 'ETAY')  JCODE = 3        IF (KNAMM .EQ. 'DETAY') JCODE = 4        IF (JCODE .NE. 0) THEN          ICODE = 27          GO TO 200        ENDIFCC     ACCELERATOR PHASE ADVANCEC        IF (KNAMM .EQ. 'PSIX') JCODE = 1        IF (KNAMM .EQ. 'PSIY') JCODE = 3        IF (JCODE .NE. 0) THEN          ICODE = -15          GO TO 200        ENDIF      ENDIF      GO TO 300CC     INDICATE MATRIX ELEMENT IDENTIFIEDC  200 INAME = 1  300 CONTINUE      RETURN      END